"use client";

import type { ReactNode } from "react";
import {
  Button,
  Disclosure,
  DisclosureGroup,
  DisclosurePanel,
  Heading,
  type DisclosureGroupProps,
  type DisclosureProps,
} from "react-aria-components";
import { accordionDefaults, type AccordionSpecProps } from "../generated/accordion.types";
import { cx } from "../utils/cx";
import { ChevronDownIcon } from "../utils/icons";

export interface AccordionProps
  extends AccordionSpecProps,
    Omit<DisclosureGroupProps, keyof AccordionSpecProps | "className" | "children"> {
  className?: string;
}

export function Accordion({
  allowsMultipleExpanded = accordionDefaults.allowsMultipleExpanded,
  isDisabled = accordionDefaults.isDisabled,
  children,
  className,
  ...rest
}: AccordionProps) {
  return (
    <DisclosureGroup
      {...rest}
      allowsMultipleExpanded={allowsMultipleExpanded}
      isDisabled={isDisabled}
      className={cx("flex w-full flex-col divide-y divide-[var(--rd-color-border-default)] overflow-hidden rounded-[var(--rd-radius-overlay)] border border-[var(--rd-color-border-default)] [box-shadow:var(--rd-elevation-raised)]", className)}
    >
      {children}
    </DisclosureGroup>
  );
}

export interface AccordionItemProps extends Omit<DisclosureProps, "className" | "children"> {
  /** The section heading; also the button's accessible name. */
  title: ReactNode;
  children: ReactNode;
  /** Heading level for the section headings. Match your page outline. */
  headingLevel?: 2 | 3 | 4 | 5 | 6;
  className?: string;
}

export function AccordionItem({ title, children, headingLevel = 3, className, ...rest }: AccordionItemProps) {
  return (
    <Disclosure {...rest} className={cx("group", className)}>
      <Heading level={headingLevel} className="m-0">
        <Button
          slot="trigger"
          className={cx(
            "flex w-full items-center justify-between gap-4 px-4 py-3.5 text-start text-sm font-medium outline-none",
            "text-[var(--rd-color-text-default)] data-[hovered]:bg-[var(--rd-color-surface-subtle)]",
            "data-[focus-visible]:ring-2 data-[focus-visible]:ring-inset data-[focus-visible]:ring-[var(--rd-color-focus-ring)]",
            "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50 data-[disabled]:bg-transparent",
          )}
        >
          {title}
          <span
            aria-hidden="true"
            className="shrink-0 text-[var(--rd-color-text-muted)] transition-transform duration-200 group-data-[expanded]:rotate-180 motion-reduce:transition-none"
          >
            <ChevronDownIcon />
          </span>
        </Button>
      </Heading>
      <DisclosurePanel className="px-4 pb-4 text-sm text-[var(--rd-color-text-default)]">{children}</DisclosurePanel>
    </Disclosure>
  );
}

// Generated by rdloom codegen from specs/accordion.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** A stack of sections whose content expands and collapses under a heading, like an FAQ. Use with AccordionItem. */
export interface AccordionSpecProps {
  /**
   * Lets several sections be open at once. Otherwise opening one closes the others.
   * @default false
   */
  allowsMultipleExpanded?: boolean;
  /**
   * Sections open at first, by id, when uncontrolled.
   */
  defaultExpandedKeys?: Iterable<import("react-aria-components").Key>;
  /**
   * Controlled open sections, by id.
   */
  expandedKeys?: Iterable<import("react-aria-components").Key>;
  /**
   * Disables every section.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Called with the ids of the open sections.
   */
  onExpandedChange?: (keys: Set<import("react-aria-components").Key>) => void;
  /**
   * AccordionItem elements.
   */
  children: ReactNode;
}

export const accordionDefaults = {
  allowsMultipleExpanded: false,
  isDisabled: false,
} as const;

export const accordionMeta = {
  "name": "Accordion",
  "version": "0.1.0",
  "status": "experimental",
  "role": "group"
} as const;

