import type { ReactNode } from "react";

export const buttonVariantValues = ["primary", "secondary", "ghost", "danger"] as const;
export const buttonSizeValues = ["sm", "md", "lg"] as const;

/** Triggers an action or event, such as submitting a form or opening a dialog. */
export interface ButtonSpecProps {
  /**
   * Visual emphasis of the button.
   * @default "primary"
   */
  variant?: "primary" | "secondary" | "ghost" | "danger";
  /**
   * Height, padding and font size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Prevents interaction and dims the button.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Shows a spinner and blocks presses. The button stays focusable, is marked aria-disabled, and the pending state is announced.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Button label. Icon-only buttons must pass aria-label instead.
   */
  children: ReactNode;
  /**
   * Called when the button is pressed by mouse, touch or keyboard.
   */
  onPress?: () => void;
}

export const buttonDefaults = {
  variant: "primary",
  size: "md",
  isDisabled: false,
  isLoading: false,
} as const;

export const buttonMeta = {
  "name": "Button",
  "version": "0.1.0",
  "status": "experimental",
  "role": "button"
} as const;

