import type { ReactNode } from "react";

/** Lets the user turn a single option on or off, with an optional indeterminate state. */
export interface CheckboxSpecProps {
  /**
   * Visible label.
   */
  children: ReactNode;
  /**
   * Controlled checked state.
   */
  isSelected?: boolean;
  /**
   * Initial checked state when uncontrolled.
   * @default false
   */
  defaultSelected?: boolean;
  /**
   * Shows a dash for a partially selected group, e.g. 'select all'.
   * @default false
   */
  isIndeterminate?: boolean;
  /**
   * Prevents interaction and dims the checkbox.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the checkbox as invalid, e.g. an unaccepted required agreement.
   * @default false
   */
  isInvalid?: boolean;
  /**
   * Called with the new checked state.
   */
  onChange?: (isSelected: boolean) => void;
}

export const checkboxDefaults = {
  defaultSelected: false,
  isIndeterminate: false,
  isDisabled: false,
  isInvalid: false,
} as const;

export const checkboxMeta = {
  "name": "Checkbox",
