   * Called once with every cell a paste changes. Prefer it to onCellEdit when you paste: applying a whole paste in one update avoids state updates overwriting each other. When it isn't set, a paste calls onCellEdit once per cell.
   */
  onCellsEdit?: (edits: import("../data-grid/types").DataGridCellEdit<any>[]) => void;
  /**
   * Select a block of cells with Shift+arrows, Shift+click or by dragging. Ctrl+C copies it as spreadsheet-ready text; Ctrl+V pastes into editable cells.
   * @default true
   */
  rangeSelection?: boolean;
  /**
   * Gives you getCsv(), downloadCsv() and downloadExcel() for the rows that pass the filters. Create it with useRef<DataGridApi>(null).
   */
  apiRef?: { current: import("../data-grid/types").DataGridApi | null };
  /**
   * Your server does the sorting, filtering and paging. The grid shows the rows you pass (one page), reports what the user asked for through onQueryChange, and uses rowCount for the pager. Needs pageSize. Not combined with groupBy or getSubRows.
   * @default false
   */
  serverSide?: boolean;
  /**
   * serverSide: total rows on the server across all pages, after the current search and filters.
   */
  rowCount?: number;
  /**
   * serverSide: called on mount and whenever the sort, filters, search or page change. Typing in a filter waits queryDelay ms; sorting and paging fire at once. Fetch, then pass the new data, rowCount and isLoading.
   */
  onQueryChange?: (query: import("../data-grid/types").DataGridQuery) => void;
  /**
   * serverSide: milliseconds to wait after the last keystroke in a filter or search before calling onQueryChange.
   * @default 250
   */
  queryDelay?: number;
  /**
   * A small handle on the corner of the selection: drag it to fill the cells it covers, continuing numbers (2, 4 gives 6, 8), text that ends in a number (Item 1 gives Item 2), ISO dates and otherwise repeating the values. Ctrl+D and Ctrl+R fill down and right from the keyboard. Needs rangeSelection and an edit handler (onCellEdit or onCellsEdit); only editable cells are written.
   * @default true
   */
  fillHandle?: boolean;
  /**
   * Adds a menu to every column header: sort, pin, reset width, hide, and show hidden columns again. Alt+Down, Shift+F10 or the Menu key on a header opens it.
   * @default false
   */
  columnMenu?: boolean;
  /**
   * Adds a drag handle column. Rows can be dragged, or moved with Alt+Up and Alt+Down. The grid reports the move through onRowReorder; you reorder your data. Off while sorting, filtering, grouping or serverSide is in use, because the rows are no longer in your data's order.
   * @default false
   */
  rowReorder?: boolean;
  /**
   * Called with { rowId, fromIndex, toIndex } when a row is moved. Apply it with reorderRows(rows, move).
   */
  onRowReorder?: (move: import("../data-grid/types").DataGridRowMove) => void;
  /**
   * Marks the grid busy and shows a loading message.
   * @default false
   */
  isLoading?: boolean;
  /**
   * Shown when there are no rows to display.
   * @default "No rows"
   */
  emptyMessage?: string;
  /**
   * Called on Enter or double-click on a row, e.g. to open details.
   */
  onRowAction?: (row: any) => void;
  /**
   * Called with the rows that match the search and column filters, in display order, whenever they change. Use it for counts and totals.
   */
  onFilteredDataChange?: (rows: any[]) => void;
  /**
   * Column ids to group rows by, outermost first. Group rows show the value, a row count, and a total in each column that sets aggregationFn ('sum', 'mean', 'min', 'max', 'count', 'uniqueCount' or a function).
   */
  groupBy?: readonly string[];
  /**
   * Start with every group, tree row and detail panel open.
   * @default false
   */
  defaultExpanded?: boolean;
  /**
   * Tree data: returns a row's children. Rows with children get an expand toggle and are indented by depth. Search keeps a parent when a child matches.
   */
  getSubRows?: (row: any) => readonly any[] | undefined;
  /**
   * Master-detail: content shown in a panel under a row when it's expanded.
   */
  renderDetail?: (row: any) => import("react").ReactNode;
  /**
   * Height of each detail panel in px; the panel scrolls if its content is taller.
   * @default 200
   */
  detailHeight?: number;
}

export const dataGridDefaults = {
  density: "standard",
  height: 480,
  virtualized: true,
  sortable: true,
  selectionMode: "none",
  resizableColumns: true,
  showColumnFilters: false,
  rangeSelection: true,
  serverSide: false,
  queryDelay: 250,
  fillHandle: true,
  columnMenu: false,
  rowReorder: false,
  isLoading: false,
  emptyMessage: "No rows",
  defaultExpanded: false,
  detailHeight: 200,
} as const;

export const dataGridMeta = {
  "name": "DataGrid",
  "version": "0.9.0",
  "status": "experimental",
  "role": "grid"
} as const;

