import { Response } from "@rdloom/react";

const reply = `## Quarterly summary

Revenue grew **12%** over last quarter, driven by _new subscriptions_. The three biggest changes:

1. Annual plans rose to \`38%\` of sign-ups
2. Churn fell below 2%
3. Support tickets per customer dropped

| Region | Revenue | Change |
| :----- | ------: | -----: |
| Europe | $412K | +9% |
| Americas | $655K | +14% |

> Numbers are preliminary until the books close.

\`\`\`ts
const growth = (now: number, before: number) => (now - before) / before;
\`\`\`

See the [full report](https://example.com/report) for details.`;

export default function ResponseMarkdownExample() {
  return (
    <div className="w-[34rem] max-w-full">
      <Response>{reply}</Response>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Button, Response } from "@rdloom/react";

const reply = "Checking the numbers now. **Sales rose in March**, and the biggest gain came from the new annual plan:\n\n- Annual plans: up 18%\n- Monthly plans: flat\n\n```sql\nSELECT month, SUM(total) FROM orders GROUP BY month;\n```";

// The text arrives a few characters at a time. Pass isStreaming while it does: the caret shows, and
// a screen reader waits for the finished text instead of reading every fragment.
export default function ResponseStreamingExample() {
  const [shown, setShown] = useState(0);
  const [run, setRun] = useState(0);
  const done = shown >= reply.length;

  useEffect(() => {
    setShown(0);
    const id = setInterval(() => setShown((n) => (n >= reply.length ? n : n + 3)), 40);
    return () => clearInterval(id);
  }, [run]);

  return (
    <div className="flex w-[34rem] max-w-full flex-col items-center gap-3">
      <Response className="w-full" isStreaming={!done}>{reply.slice(0, shown)}</Response>
      <Button variant="secondary" size="sm" onPress={() => setRun((n) => n + 1)}>
        Replay
      </Button>
    </div>
  );
}

