import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { rippleDefaults, type RippleSpecProps } from "../generated/ripple.types";
import { cx } from "../utils/cx";

// Plain markup with no hooks, so it also works in a React Server Component.

export interface RippleProps extends RippleSpecProps, Omit<HTMLAttributes<HTMLDivElement>, keyof RippleSpecProps | "className"> {
  className?: string;
}

/** Concentric rings that swell outward from the centre, as a calm backdrop. Content goes in front of them. */
export const Ripple = forwardRef<HTMLDivElement, RippleProps>(function Ripple(
  { children, size = rippleDefaults.size, rings = rippleDefaults.rings, duration = rippleDefaults.duration, color, isPaused = rippleDefaults.isPaused, className, style, ...rest },
  ref,
) {
  const count = Math.max(1, Math.min(12, Math.round(rings)));
  return (
    <div
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("relative isolate flex items-center justify-center overflow-hidden", className)}
      style={{ ...({ "--rdm-d": `${duration}s`, ...(color ? { "--rdm-c": color } : {}) } as CSSProperties), ...style }}
    >
      <div aria-hidden="true" className="pointer-events-none absolute inset-0 -z-10">
        {Array.from({ length: count }, (_, i) => (
          <span
            key={i}
            className="rdm-ring"
            style={{ width: size + i * 70, height: size + i * 70, animationDelay: `${i * 0.18}s`, opacity: Math.max(0.15, 0.9 - i * 0.12) }}
          />
        ))}
      </div>
      {children}
    </div>
  );
});

// Generated by rdloom codegen from specs/ripple.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** Concentric rings that swell outward from the centre, as a calm backdrop behind a heading or a call to action. Content goes in front of the rings. */
export interface RippleSpecProps {
  /**
   * Content shown in front of the rings, centred.
   */
  children?: ReactNode;
  /**
   * Diameter in pixels of the innermost ring.
   * @default 210
   */
  size?: number;
  /**
   * How many rings, 1 to 12.
   * @default 6
   */
  rings?: number;
  /**
   * Seconds for one swell.
   * @default 4
   */
  duration?: number;
  /**
   * Colour of the rings, any CSS colour. Defaults to the strong border colour.
   */
  color?: string;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
  /**
   * Classes for the wrapper: size it and give it a background.
   */
  className?: string;
}

export const rippleDefaults = {
  size: 210,
  rings: 6,
  duration: 4,
  isPaused: false,
} as const;

export const rippleMeta = {
  "name": "Ripple",
  "version": "0.1.0",
  "status": "experimental",
  "role": "none"
} as const;

