"use client";

import { forwardRef } from "react";
import {
  FieldError,
  Input,
  Label,
  Text,
  TextArea,
  TextField as AriaTextField,
  type TextFieldProps as AriaTextFieldProps,
} from "react-aria-components";
import { textFieldDefaults, type TextFieldSpecProps } from "../generated/text-field.types";
import { cx } from "../utils/cx";

export interface TextFieldProps
  extends TextFieldSpecProps,
    Omit<AriaTextFieldProps, keyof TextFieldSpecProps | "className" | "children"> {
  className?: string;
}

const control =
  "w-full bg-[var(--rd-color-surface-default)] text-[var(--rd-color-text-default)] " +
  "border border-[var(--rd-color-border-default)] rounded-[var(--rd-radius-control)] outline-none transition-colors [box-shadow:var(--rd-elevation-raised)] " +
  "placeholder:text-[var(--rd-color-text-muted)] " +
  "data-[hovered]:border-[var(--rd-color-border-strong)] " +
  "data-[focused]:ring-2 data-[focused]:ring-[var(--rd-color-focus-ring)] data-[focused]:border-[var(--rd-color-focus-ring)] " +
  "data-[invalid]:border-[var(--rd-color-feedback-danger)] " +
  "data-[disabled]:opacity-50 data-[disabled]:cursor-not-allowed";

const sizes: Record<NonNullable<TextFieldSpecProps["size"]>, string> = {
  sm: "px-[var(--rd-space-control-x-sm)] text-sm",
  md: "px-[var(--rd-space-control-x)] text-sm",
  lg: "px-[var(--rd-space-control-x-lg)] text-base",
};
const heights: Record<NonNullable<TextFieldSpecProps["size"]>, string> = {
  sm: "h-[var(--rd-size-control-sm)]",
  md: "h-[var(--rd-size-control-md)]",
  lg: "h-[var(--rd-size-control-lg)]",
};

export const TextField = forwardRef<HTMLDivElement, TextFieldProps>(function TextField(
  {
    label,
    description,
    errorMessage,
    placeholder,
    size = textFieldDefaults.size,
    multiline = textFieldDefaults.multiline,
    isDisabled = textFieldDefaults.isDisabled,
    // Left undefined unless passed: React Aria treats any defined isInvalid as
    // controlled and would hide its own validation (required, min/max...).
    isInvalid,
    isRequired = textFieldDefaults.isRequired,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaTextField
      {...rest}
      ref={ref}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isRequired={isRequired}
      className={cx("flex flex-col gap-2", className)}
    >
      <Label className="text-sm font-medium text-[var(--rd-color-text-default)]">
        {label}
        {isRequired && <span aria-hidden="true" className="text-[var(--rd-color-feedback-danger)]"> *</span>}
      </Label>
      {multiline ? (
        <TextArea placeholder={placeholder} className={cx(control, sizes[size], "min-h-24 py-2 resize-y")} />
      ) : (
        <Input placeholder={placeholder} className={cx(control, sizes[size], heights[size])} />
      )}
      {description && (
        <Text slot="description" className="text-xs text-[var(--rd-color-text-muted)]">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-[var(--rd-color-feedback-danger)]">{errorMessage}</FieldError>
    </AriaTextField>
  );
});

// Generated by rdloom codegen from specs/text-field.spec.json (v0.1.1).
// Do not edit. Change the spec and run `npm run gen`.

export const textFieldSizeValues = ["sm", "md", "lg"] as const;

/** Single-line or multi-line text input with a label, help text and error message. */
export interface TextFieldSpecProps {
  /**
   * Visible label. Required so the field is always named.
   */
  label: string;
  /**
   * Help text shown under the input.
   */
  description?: string;
  /**
   * Shown when the field is invalid.
   */
  errorMessage?: string;
  /**
   * Example value. Never a replacement for the label.
   */
  placeholder?: string;
  /**
   * Height and font size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Renders a textarea instead of an input.
   * @default false
   */
  multiline?: boolean;
  /**
   * Prevents editing and dims the field.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the value as invalid and shows errorMessage.
   * @default false
   */
  isInvalid?: boolean;
  /**
   * Marks the field as required for form submission.
   * @default false
   */
  isRequired?: boolean;
  /**
   * Controlled value.
   */
  value?: string;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: string;
  /**
   * Called with the new value on every edit.
   */
  onChange?: (value: string) => void;
}

export const textFieldDefaults = {
  size: "md",
  multiline: false,
  isDisabled: false,
  isInvalid: false,
  isRequired: false,
} as const;

export const textFieldMeta = {
  "name": "TextField",
  "version": "0.1.1",
  "status": "experimental",
  "role": "textbox"
} as const;

