import { forwardRef, type CSSProperties, type HTMLAttributes } from "react";
import { textShimmerDefaults, type TextShimmerSpecProps } from "../generated/text-shimmer.types";
import { cx } from "../utils/cx";

// Plain markup with no hooks, so it also works in a React Server Component.

export interface TextShimmerProps
  extends TextShimmerSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof TextShimmerSpecProps | "className"> {
  className?: string;
}

/** Text with a band of light sweeping across it. The words stay real text: selectable and readable. */
export const TextShimmer = forwardRef<HTMLSpanElement, TextShimmerProps>(function TextShimmer(
  { children, duration = textShimmerDefaults.duration, baseColor, highlightColor, isPaused = textShimmerDefaults.isPaused, className, style, ...rest },
  ref,
) {
  const vars: Record<string, string> = { "--rdm-d": `${duration}s` };
  if (baseColor) vars["--rdm-base"] = baseColor;
  if (highlightColor) vars["--rdm-hi"] = highlightColor;
  return (
    <span
      {...rest}
      ref={ref}
      data-rdm-paused={isPaused || undefined}
      className={cx("rdm-text-shimmer", className)}
      style={{ ...(vars as CSSProperties), ...style }}
    >
      {children}
    </span>
  );
});

// Generated by rdloom codegen from specs/text-shimmer.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

/** Text with a band of light sweeping across it, for a loading message or a quiet accent. The words stay real text: selectable and read as normal. */
export interface TextShimmerSpecProps {
  /**
   * The text.
   */
  children: ReactNode;
  /**
   * Seconds for one sweep.
   * @default 2.8
   */
  duration?: number;
  /**
   * The resting colour of the text, any CSS colour. Defaults to the muted text colour.
   */
  baseColor?: string;
  /**
   * The colour of the passing light, any CSS colour. Defaults to the main text colour.
   */
  highlightColor?: string;
  /**
   * Stops the animation. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const textShimmerDefaults = {
  duration: 2.8,
  isPaused: false,
} as const;

export const textShimmerMeta = {
  "name": "TextShimmer",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;

